def solve():
    t = int(input())
    results = []

    for _ in range(t):
        n, m, k = map(int, input().split())
        cards_per_player = n // k

        if m <= cards_per_player:
            # One player can have all m jokers, others have 0
            results.append(m)
        else:
            # One player has cards_per_player jokers
            # Remaining jokers: m - cards_per_player
            # Shared among k-1 players
            max_other = (m - cards_per_player + k - 2) // (k - 1)  # ceil division

            if cards_per_player > max_other:
                results.append(cards_per_player - max_other)
            else:
                results.append(0)

    for result in results:
        print(result)

solve()
