numbers = list(range(1, limit + 1))

# Try to find a combination using a more systematic approach
result = []
total = 0
used = [False] * (limit + 1)

# First, try to use large numbers
for num in reversed(numbers):
    if not used[num] and total + lowbits[num - 1] <= sum_val:
        result.append(num)
        total += lowbits[num - 1]
        used[num] = True

# If we haven't reached the target, try to fill in with smaller numbers
if total < sum_val:
    # Try to use smaller numbers, but be careful not to exceed the limit
    for num in range(1, limit + 1):
        if not used[num] and total + lowbits[num - 1] <= sum_val:
            result.append(num)
            total += lowbits[num - 1]
            used[num] = True
            if total == sum_val:
                break

if total == sum_val:
    print(len(result))
    print(' '.join(map(str, result)))
else:
    print(-1)
