def is_lucky(num):
    """Check if a number is lucky (only contains digits 4 and 7)"""
    while num > 0:
        digit = num % 10
        if digit not in {4, 7}:
            return False
        num //= 10
    return True


def solve():
    n = int(input())
    edges = [[] for _ in range(n)]

    for _ in range(n - 1):
        u, v, w = map(int, input().split())
        if not is_lucky(w):
            edges[u - 1].append(v - 1)
            edges[v - 1].append(u - 1)

    # Find connected components
    visited = [False] * n
    component_sizes = []

    for i in range(n):
        if not visited[i]:
            stack = [i]
            visited[i] = True
            size = 0
            while stack:
                current = stack.pop()
                size += 1
                for neighbor in edges[current]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            component_sizes.append(size)

    # Calculate answer
    total = 0
    for s in component_sizes:
        # Each component of size s contributes s * (n - s) * (n - s - 1)
        total += s * (n - s) * (n - s - 1)

    print(total)

solve()
