def count_valid_intervals(s):
    n = len(s)
    # Find all valid triplets (i, k) where s[i] = s[i+k] = s[i+2k]
    triplets = []
    for i in range(n):
        for k in range(1, n - i + 1):
            if i + 2 * k < n:
                if s[i] == s[i + k] == s[i + 2 * k]:
                    triplets.append((i, i + 2 * k))

    # For each interval [l, r], check if it contains at least one triplet
    result = 0
    for l in range(1, n + 1):
        for r in range(l, n + 1):
            # Check if any triplet is contained in [l, r]
            contains_triplet = False
            for start, end in triplets:
                if start >= l and end <= r:
                    contains_triplet = True
                    break
            if contains_triplet:
                result += 1

    return result

s = input().strip()
n = len(s)
print(count_valid_intervals(s))
