def digital_root(x):
    if x <= 9:
        return x
    return digital_root(sum(int(d) for d in str(x)))

N = int(input())

count = 0

for A in range(1, N + 1):
    a = digital_root(A)
    for B in range(1, N + 1):
        b = digital_root(B)

        # Try different values of k (number of digits in b)
        k = 1
        if b >= 10:
            k += 1  # b is 2 digits

        d_ab = digital_root(int(str(a) + str(b)))

        # Count how many C's have d(C) = d_ab
        if d_ab == 0:
            # Digital root 9 means C % 9 == 0, but C != 0
            count_target = N - (N // 9)  # Total numbers - multiples of 9
        else:
            # Digital root d_ab means C % 9 == d_ab
            count_target = N // 9  # Multiples of 9 with remainder d_ab

        count += count_target

print(count)
