def lowbit(x):
    """Calculate the least significant 1 bit of x"""
    return x & -x

sum_val, limit = map(int, input().split())

# Calculate lowbit for each number from 1 to limit
lowbits = [(i, lowbit(i)) for i in range(1, limit + 1)]

# Sort by lowbit in descending order
lowbits.sort(key=lambda x: x[1], reverse=True)

result = []
current_sum = sum_val

for num, lb in lowbits:
    if current_sum >= lb:
        result.append(num)
        current_sum -= lb
        if current_sum == 0:
            break

if current_sum == 0:
    print(len(result))
    print(' '.join(map(str, result)))
else:
    print(-1)
"}

