def solve():
    s = input().strip()
    t = input().strip()

    len_s = len(s)
    len_t = len(t)

    # dp[i][j]: max occurrences after processing first i characters of s,
    # with a partial match of length j with t
    dp = [[-1] * len_t for _ in range(len_s + 1)]
    dp[0][0] = 0

    for i in range(len_s):
        for j in range(len_t):
            if dp[i][j] == -1:
                continue

            # Try to extend the partial match
            if s[i] == t[j]:
                if j + 1 == len_t:
                    # Complete match
                    dp[i+1][j+1] = max(dp[i+1][j+1], dp[i][j] + 1)
                else:
                    dp[i+1][j+1] = max(dp[i+1][j+1], dp[i][j])

            # Try to not extend (or start a new partial match)
            # Actually, we can also try to start a new partial match
            # by considering different starting points
            for k in range(len_t):
                if s[i] == t[k]:
                    if k == len_t:
                        dp[i+1][k] = max(dp[i+1][k], dp[i][j] + 1)
                    else:
                        dp[i+1][k] = max(dp[i+1][k], dp[i][j])

    answer = max(dp[len_s])
    print(answer)

