def path_contains(n, x, y):
    """Check if y is in path(x)"""
    if y > n:
        return False
    current = x
    while current != 1:
        if current == y:
            return True
        if current % 2 == 0:
            current = current // 2
        else:
            current = current - 1
    return y == 1 or y == current

def count_in_path(n, y):
    """Count how many numbers x (1 ≤ x ≤ n) have y in their path"""
    count = 0
    for x in range(1, n + 1):
        if path_contains(n, x, y):
            count += 1
    return count

def solve(n, k):
    for y in range(n, 0, -1):
        c = count_in_path(n, y)
        if c >= k:
            return y
    return 1

