import sys

def solve():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    s = data[0]
    n = int(data[1])
    boring_strings = data[2:2+n]

    # Find all positions where boring strings appear
    boring_positions = {}
    for b in boring_strings:
        for i in range(len(s) - len(b) + 1):
            if s[i:i+len(b)] == b:
                if i not in boring_positions:
                    boring_positions[i] = []
                boring_positions[i].append(b)

    max_len = 0
    max_pos = 0

    # Try each starting position
    for start in range(len(s)):
        if start in boring_positions:
            continue  # Skip if start position itself is boring

        end = start
        while end < len(s):
            # Check if extending to end+1 would cause a boring string
            next_end = end + 1
            if next_end not in boring_positions:
                end = next_end
            else:
                # Check if any boring string appears in s[start:end+1]
                found_boring = False
                for pos, b_list in boring_positions.items():
                    if start <= pos < next_end:
                        found_boring = True
                        break
                if not found_boring:
                    end = next_end
                else:
                    break

        # Check if s[start:end] is valid
        valid = True
        for pos, b_list in boring_positions.items():
            if start <= pos < end:
                valid = False
                break

        if valid:
            if end - start > max_len or (end - start == max_len and start < max_pos):
                max_len = end - start
                max_pos = start

    print(max_len, max_pos)

if __name__ == "__main__":
    solve()
