def count_occurrences(string, pattern):
    """Count occurrences of pattern in string using KMP."""
    if not pattern:
        return 0

    # Build KMP failure function
    failure = [0] * len(pattern)
    j = 0
    for i in range(1, len(pattern)):
        while j > 0 and pattern[i] != pattern[j]:
            j = failure[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
            failure[i] = j

    # KMP search
    j = 0
    count = 0
    for char in string:
        while j > 0 and char != pattern[j]:
            j = failure[j - 1]
        if char == pattern[j]:
            j += 1
        if j == len(pattern):
            count += 1
            j = failure[j - 1]
    return count

# Build KMP automata for both s and t
def build_automaton(pattern):
    """Build KMP automaton for a pattern."""
    if not pattern:
        return [0] * 26

    # Build failure function
    failure = [0] * len(pattern)
    j = 0
    for i in range(1, len(pattern)):
        while j > 0 and pattern[i] != pattern[j]:
            j = failure[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
            failure[i] = j

    # Build transition table
    transitions = [[0] * 26 for _ in range(len(pattern) + 1)]
    for state in range(len(pattern) + 1):
        for ch in range(26):
            if state < len(pattern):
                char = chr(ord('a') + ch)
                if char == pattern[state]:
                    transitions[state][ch] = state + 1
                else:
                    transitions[state][ch] = transitions[failure[state - 1]][ch]
            else:
                transitions[state][ch] = 0
    return transitions

def solve():
    # Read input
    c = input().strip()
    s = input().strip()
    t = input().strip()

    # Build automata
    automaton_s = build_automaton(s)
    automaton_t = build_automaton(t)

    # Dynamic programming table:
    # dp[i][state_s][state_t] = max value achievable
    # i: current position in c
    # state_s: length of prefix of s matching current suffix
    # state_t: length of prefix of t matching current suffix
    # value: max value of f(c', s) - f(c', t)

    n = len(c)
    dp = [[[-10**9] * (len(t) + 1) for _ in range(len(s) + 1)] for _ in range(n + 1)]
    dp[0][0][0] = 0

    for i in range(n):
        for state_s in range(len(s) + 1):
            for state_t in range(len(t) + 1):
                if dp[i][state_s][state_t] == -10**9:
                    continue

                # Try all possible characters at position i
                for ch in range(26):
                    next_state_s = automaton_s[state_s][ch]
                    next_state_t = automaton_t[state_t][ch]

                    # Check if we completed an occurrence
                    completed_s = next_state_s == len(s)
                    completed_t = next_state_t == len(t)

                    # Update the value
                    value = dp[i][state_s][state_t]
                    if completed_s:
                        value += 1
                    if completed_t:
                        value -= 1

                    # Update the next state
                    dp[i + 1][next_state_s][next_state_t] = max(
                        dp[i + 1][next_state_s][next_state_t], 
                        value
                    )

    # Find the maximum value achievable at the end
    max_value = max(dp[n][state_s][state_t] for state_s in range(len(s) + 1) for state_t in range(len(t) + 1))

    print(max_value)

solve()
