cursor = 0

def is_correct(text):
    if '(' not in text and ')' not in text:
        return True

    # Check if text is CT
    # CT rules: 
    # 1. If text has no brackets, it's CT
    # 2. If text starts with '(' and ends with ')', and the middle is CT
    # 3. If text can be split into two CT parts

    # Rule 2: starts with '(' and ends with ')'
    if text[0] == '(' and text[-1] == ')':
        # Check if middle is CT
        if is_correct(text[1:-1]):
            return True

    # Rule 3: split into two CT parts
    for i in range(len(text)):
        if is_correct(text[:i]) and is_correct(text[i:]):
            return True

    return False

# For min_colors, we need to count the number of layers in the bracket sequence
# This is equivalent to counting the number of times we enter and exit nested brackets

def min_colors(text):
    if '(' not in text and ')' not in text:
        return 1  # Any text without brackets is considered CT with 1 "color"

    stack = []
    color_count = 0

    for i, char in enumerate(text):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                stack.pop()
                if stack:
                    color_count += 1

    return color_count + 1  # Add 1 for the outermost layer

results = []

for i in range(n):
    char = s[i]

    if char == 'L':
        if cursor > 0:
            cursor -= 1
    elif char == 'R':
        cursor += 1
    else:
        # Write character at cursor position
        line[cursor] = char

    # Build the text
    text = ''.join(line)

    if is_correct(text):
        results.append(str(min_colors(text)))
    else:
        results.append("-1")

print(' '.join(results))
