text = []  # empty text initially
cursor = 0  # starts at position 0 (leftmost)

def is_valid_ct(text):
    """Check if text is a correct text (CT)"""
    # CT is a valid bracket sequence (ignoring whitespace)
    stack = []
    for ch in text:
        if ch == '(':
            stack.append(ch)
        elif ch == ')':
            if not stack or stack[-1] != '(':
                return False
            stack.pop()
    return not stack

def min_colors(text):
    """Compute minimum number of colors for valid CT"""
    if not text:
        return 0

    # Find the bracket sequence (ignoring whitespace)
    brackets = []
    for ch in text:
        if ch in "())(":
            brackets.append(ch)

    if not brackets:
        return 0

    # Compute minimum colors (maximum nesting depth)
    depth = 0
    max_depth = 0
    stack = []
    for ch in brackets:
        if ch == '(':
            stack.append(ch)
            depth += 1
            max_depth = max(max_depth, depth)
        else:  # ')'
            stack.pop()
            depth -= 1
    return max_depth

for i in range(n):
    cmd = s[i]

    if cmd == 'L':
        if cursor > 0:
            cursor -= 1
    elif cmd == 'R':
        cursor += 1
    else:
        # Write character at cursor position
        text.insert(cursor, cmd)
        cursor += 1  # move right after writing

    # Check if valid CT
    if is_valid_ct(text):
        print(min_colors(text), end=' ')
    else:
        print(-1, end=' ')
