        for i in range(n):
            # Start at i, check if we can alternate between two types
            seen = {}
            seen[i] = 0  # color 0
            current = i
            color = 0
            count = 0

            while True:
                current = (current + 1) % n
                count += 1

                # Check if we can alternate
                if t[current] == t[seen[current]]:
                    # Same type, color the same
                    seen[current] = color
                    color = 1 - color
                    continue

                # Different type, need different color
                if t[current] == t[seen[current]]:
                    # Conflict, not an alternating cycle
                    break

