def is_lucky(num):
    """Check if a number is lucky (contains only digits 4 and 7)"""
    s = str(num)
    return all(c in '47' for c in s)


def solve():
    import sys
    input = sys.stdin.read()
    data = input.split()

    n = int(data[0])
    edges = []

    idx = 1
    for _ in range(n - 1):
        u = int(data[idx])
        v = int(data[idx + 1])
        w = int(data[idx + 2])
        idx += 3
        edges.append((u, v, w))

    # Build graph without lucky edges
    from collections import defaultdict, deque

    non_lucky_graph = defaultdict(list)

    for u, v, w in edges:
        if not is_lucky(w):
            non_lucky_graph[u].append(v)
            non_lucky_graph[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)
    components = []

    for vertex in range(1, n + 1):
        if not visited[vertex]:
            queue = deque([vertex])
            visited[vertex] = True
            component = [vertex]
            while queue:
                current = queue.popleft()
                for neighbor in non_lucky_graph[current]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
                        component.append(neighbor)
            components.append(component)

    # Count vertices in each component
    comp_count = [0] * (n + 1)
    for comp in components:
        for v in comp:
            comp_count[v] = len(comp)

    # For each vertex, count vertices in different components
    total = 0
    for i in range(1, n + 1):
        # j and k must be in different components than i
        count = 0
        for j in range(1, n + 1):
            if j != i and comp_count[j] != comp_count[i]:
                count += 1
        total += count * count

    print(total)

if __name__ == "__main__":
    solve()
