from collections import defaultdict

def count_occurrences(text, pattern):
    """Count the number of occurrences of pattern in text."""
    count = 0
    i = 0
    n = len(pattern)
    while i <= len(text) - n:
        match = True
        for j in range(n):
            if text[i+j] != pattern[j]:
                match = False
                break
        if match:
            count += 1
            i += n
        else:
            i += 1
    return count

def solve():
    c = input().strip()
    s = input().strip()
    t = input().strip()

    # We want to maximize f(c', s) - f(c', t)
    # We'll use DP where state = (pos, state_s, state_t)
    # pos: current position in string c
    # state_s: current state of matching s (0 to len(s))
    # state_t: current state of matching t (0 to len(t))
    # value: maximum value of f(c', s) - f(c', t) we can achieve from this state

    n = len(c)
    len_s = len(s)
    len_t = len(t)

