def solve():
    s = input().strip()
    t = input().strip()

    n, m = len(s), len(t)

    # leftmost[i] = the leftmost position in s where we can match t[0..i-1]
    leftmost = [0] * (m + 1)

    # rightmost[i] = the rightmost position in s where we can match t[i..m-1]
    rightmost = [0] * (m + 1)

    leftmost[0] = 0
    rightmost[m] = n

    # Find leftmost matches
    for i in range(1, m + 1):
        for j in range(n):
            if s[j] == t[i-1] and leftmost[i-1] <= j:
                leftmost[i] = j
                break

    # Find rightmost matches
    for i in range(m, 0, -1):
        for j in range(n, -1, -1):
            if s[j] == t[i-1] and rightmost[i] >= j:
                rightmost[i] = j
                break

    max_length = 0
    # Try to match t[0..k] from the left and t[k..m-1] from the right
    for k in range(m + 1):
        if leftmost[k] < rightmost[k]:
            length = rightmost[k] - leftmost[k] - 1
            max_length = max(max_length, length)

    print(max_length)

solve()
