def solve():
    s = input().strip()
    t = input().strip()

    n, m = len(s), len(t)

    # leftmost[i] = the leftmost position in s where we can match t[0..i-1]
    leftmost = [0] * (m + 1)

    # rightmost[i] = the rightmost position in s where we can match t[i..m-1]
    rightmost = [0] * (m + 1)

    leftmost[0] = 0
    rightmost[m] = n

    # Find leftmost matches
    for i in range(1, m + 1):
        for j in range(n):
            if s[j] == t[i-1] and leftmost[i-1] <= j:
                leftmost[i] = j
                break

