    for i in range(m, 0, -1):
        for j in range(n, -1, -1):
            if s[j] == t[i-1] and rightmost[i] >= j:
                rightmost[i] = j
                break

    max_length = 0
    # Try to match t[0..k] from the left and t[k..m-1] from the right
    for k in range(m + 1):
        if leftmost[k] < rightmost[k]:
            length = rightmost[k] - leftmost[k] - 1
            max_length = max(max_length, length)

    print(max_length)

