sum_limit = list(map(int, input().split()))
sum_val = sum_limit[0]
limit = sum_limit[1]

# Function to calculate lowbit
def lowbit(x):
    return x & -x

# Work from smallest power of 2 up
result = []
remaining = sum_val

# Find the smallest power of 2 >= 1
power = 1
while power <= limit:
    # Pick the largest number <= limit with lowbit == power
    num = power
    while num <= limit:
        if lowbit(num) == power:
            if num not in result:
                result.append(num)
                remaining -= power
                break
            num += power
        else:
            break

if remaining == 0:
    print(len(result))
    print(' '.join(map(str, result)))
else:
    print(-1)
