import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    nums = list(map(int, data[2:2+n]))

    # dp[i] = True if we can achieve remainder i
    dp = [False] * m
    dp[0] = False  # We can't achieve remainder 0 with an empty subsequence

    for num in nums:
        temp = [False] * m
        for r in range(m):
            if dp[r]:
                new_r = (r + num) % m
                temp[new_r] = True
        # Merge temp with dp
        for r in range(m):
            dp[r] = dp[r] or temp[r]

    print("YES" if dp[0] else "NO")

if __name__ == "__main__":
    solve()
"}

