def solve():
    t = int(input())
    results = []

    for _ in range(t):
        n, m = map(int, input().split())
        matrix = []

        for _ in range(n):
            matrix.append(list(map(int, input().split())))

        # Create a dictionary to map each element to its group
        groups = {}

        for i in range(n):
            for j in range(m):
                # Find the representative of the group
                rep_i = min(i, n-1-i)
                rep_j = min(j, m-1-j)
                rep = (rep_i, rep_j)

                if rep not in groups:
                    groups[rep] = []

                # Add all elements in this group
                for di, dj in [(0, 0), (0, m-1), (n-1, 0), (n-1, m-1)]:
                    ni = i + di
                    nj = j + dj
                    if ni < 0 or ni >= n or nj < 0 or nj >= m:
                        continue

                    groups[rep].append(matrix[ni][nj])

        # Calculate minimum operations
        total_operations = 0

        for values in groups.values():
            values.sort()
            median = values[len(values)//2]
            total_operations += sum(abs(x - median) for x in values)

        results.append(total_operations)

    for result in results:
        print(result)

