def solve():
    n = int(input())
    x_counts = {}
    y_counts = {}
    pos_counts = {}

    for _ in range(n):
        x, y = map(int, input().split())

        # Count x-coordinate
        if x in x_counts:
            x_counts[x] += 1
        else:
            x_counts[x] = 1

        # Count y-coordinate
        if y in y_counts:
            y_counts[y] += 1
        else:
            y_counts[y] = 1

        # Count positions (x, y)
        pos = (x, y)
        if pos in pos_counts:
            pos_counts[pos] += 1
        else:
            pos_counts[pos] = 1

    # Calculate pairs with same x
    same_x_pairs = 0
    for count in x_counts.values():
        same_x_pairs += count * (count - 1) // 2

    # Calculate pairs with same y
    same_y_pairs = 0
    for count in y_counts.values():
        same_y_pairs += count * (count - 1) // 2

    # Calculate pairs with same position
    same_pos_pairs = 0
    for count in pos_counts.values():
        same_pos_pairs += count * (count - 1) // 2

    # Total pairs where distances are equal
    total = same_x_pairs + same_y_pairs - same_pos_pairs

    print(total)

solve()
