import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    idx = 1

    results = []
    for _ in range(t):
        n = int(data[idx])
        m = int(data[idx + 1])
        k = int(data[idx + 2])
        idx += 3

        if m == 0:
            results.append(0)
        else:
            cards_per_player = n // k
            if m <= cards_per_player:
                results.append(m)
            else:
                x = cards_per_player
                remaining_jokers = m - cards_per_player
                remaining_players = k - 1
                y = (remaining_jokers + remaining_players - 1) // remaining_players
                results.append(x - y)

    sys.stdout.write("\n".join(map(str, results)))

if __name__ == "__main__":
    solve()
"}

