import sys

def solve(a, b):
    # We start with a sheet of size a x b
    # We keep making squares until we're left with a square

    count = 0
    while a > 0 and b > 0:
        # Make a square of size min(a, b) x min(a, b)
        size = min(a, b)
        count += 1

        # Subtract the square from the sheet
        if a > b:
            a -= size
        else:
            b -= size

    return count

