def solve():
    n, b, a = map(int, input().split())
    s = list(map(int, input().split()))

    # Try different strategies:
    # 1. Use battery when sunny
    battery1 = b
    accumulator1 = a
    for i in range(n):
        if battery1 > 0 and s[i] == 1:
            battery1 -= 1
            accumulator1 = min(accumulator1 + 1, a)
        elif accumulator1 > 0:
            accumulator1 -= 1
        else:
            break
    result1 = i + 1

    # 2. Use accumulator when not sunny
    battery2 = b
    accumulator2 = a
    for i in range(n):
        if accumulator2 > 0 and s[i] == 0:
            accumulator2 -= 1
        elif battery2 > 0:
            battery2 -= 1
        else:
            break
    result2 = i + 1

    # 3. Try alternating
    battery3 = b
    accumulator3 = a
    for i in range(n):
        if battery3 > 0:
            battery3 -= 1
            if s[i] == 1:
                accumulator3 = min(accumulator3 + 1, a)
        elif accumulator3 > 0:
            accumulator3 -= 1
        else:
            break
    result3 = i + 1

    return max(result1, result2, result3)

