from collections import deque

def solve() -> None:
    n = int(input())
    h = list(map(int, input().split()))

    # BFS: nodes are skyscraper indices (1-indexed)
    queue = deque()
    queue.append((1, 0))  # (current skyscraper, number of jumps)
    visited = [False] * (n + 1)
    visited[1] = True

    while queue:
        i, jumps = queue.popleft()

        # Try adjacent (i+1)
        if i + 1 <= n and not visited[i + 1]:
            visited[i + 1] = True
            queue.append((i + 1, jumps + 1))
            if i + 1 == n:
                print(jumps + 1)
                return

        # Try jump where all between are strictly less than both
        # Need h_j > h_i and all between are < h_i
        for j in range(i + 1, n + 1):
            if h[j - 1] > h[i - 1]:
                # Check if all between are < h_i
                valid = True
                for k in range(i, j):
                    if h[k - 1] >= h[i - 1]:
                        valid = False
                        break
                if valid:
                    if not visited[j]:
                        visited[j] = True
                        queue.append((j, jumps + 1))
                        if j == n:
                            print(jumps + 1)
                            return
                    break

        # Try jump where all between are strictly greater than both
        # Need h_j < h_i and all between are > h_i
        for j in range(i + 1, n + 1):
            if h[j - 1] < h[i - 1]:
                # Check if all between are > h_i
                valid = True
                for k in range(i, j):
                    if h[k - 1] <= h[i - 1]:
                        valid = False
                        break
                if valid:
                    if not visited[j]:
                        visited[j] = True
                        queue.append((j, jumps + 1))
                        if j == n:
                            print(jumps + 1)
                            return
                    break

solve()
"}

