        increment_s = 0
        increment_t = 0

        if new_k_s == len_s:
            increment_s = 1
        if new_k_t == len_t:
            increment_t = 1

        return new_k_s, new_k_t, increment_s, increment_t

    # Use dynamic programming
    dp = [[[-float('inf') for _ in range(len_t + 1)] for _ in range(len_s + 1)] for _ in range(len_c + 1)]

