def is_correct(text):
    """Check if the text is a correct text (CT)."""
    # Remove whitespace
    clean_text = ''.join(text)

    if '(' not in clean_text:
        return True  # No brackets, CT

    balance = 0
    for c in clean_text:
        if c == '(':
            balance += 1
        elif c == ')':
            balance -= 1
            if balance < 0:
                return False  # Invalid nesting

    return balance == 0  # Must be balanced


def min_colors(text):
    """Calculate minimal number of colors needed for bracket coloring."""
    # Remove whitespace
    clean_text = ''.join(text)
    if '(' not in clean_text:
        return 0  # No brackets, 0 colors needed

    max_depth = 0
    current_depth = 0
    for c in clean_text:
        if c == '(':
            current_depth += 1
            max_depth = max(max_depth, current_depth)
        elif c == ')':
            current_depth -= 1

    return max_depth


