    t, a, b = map(int, input().split())
    if a == 1 and b == 1:
        both.append(t)
    elif a == 1 and b == 0:
        alice_only.append(t)
    elif a == 0 and b == 1:
        bob_only.append(t)
    else:
        neither.append(t)

