# We need at least k books liked by Alice and k books liked by Bob
# Books liked by both contribute to both counts
# Books liked by neither should never be included

# Calculate how many more books we need for each person
needed_alice = max(0, k - k_both)
needed_bob = max(0, k - k_both)

# Pick the needed books
if needed_alice > 0 and needed_bob > 0:
    # Need books from both Alice-only and Bob-only
    if len(alice_only) < needed_alice or len(bob_only) < needed_bob:
        print(-1)
    else:
        print(sum(both) + sum(alice_only[:needed_alice]) + sum(bob_only[:needed_bob]))
elif needed_alice > 0:
    # Need only Alice-only books
    if len(alice_only) < needed_alice:
        print(-1)
    else:
        print(sum(both) + sum(alice_only[:needed_alice]))
elif needed_bob > 0:
    # Need only Bob-only books
    if len(bob_only) < needed_bob:
        print(-1)
    else:
        print(sum(both) + sum(bob_only[:needed_bob]))
else:
    # Already have enough books liked by both
    if k_both >= k:
        print(sum(both[:k]))
    else:
