from collections import deque

def solve():
    q = int(input())
    for _ in range(q):
        n = int(input())
        t = list(map(int, input().split()))

        # Build the graph where edges connect adjacent figures with different types
        graph = [[] for _ in range(n)]
        for i in range(n):
            if t[i] != t[(i + 1) % n]:
                graph[i].append((i + 1) % n)

        # Check if the graph is bipartite
        color = [-1] * n
        is_bipartite = True

        for start in range(n):
            if color[start] == -1:
                queue = deque([start])
                color[start] = 0

                while queue:
                    u = queue.popleft()
                    for v in graph[u]:
                        if color[v] == -1:
                            color[v] = 1 - color[u]
                            queue.append(v)
                        elif color[v] == color[u]:
                            is_bipartite = False
                            break
                    if not is_bipartite:
                        break
                if not is_bipartite:
                    break

        if not is_bipartite:
            # Need 3 colors for non-bipartite graph
            print(3)
            # Color with 3 colors based on BFS layers
            # We'll use 0, 1, 2 for colors 1, 2, 3
            output = [0] * n
            queue = deque([start])
            queue.append(-1)  # sentinel for BFS levels
            color[start] = 0

            while queue:
                u = queue.popleft()
                if u == -1:
                    start = queue.popleft()
                    color[start] = 0
                    queue.append(-1)
                    continue
                for v in graph[u]:
                    if color[v] == -1:
                        color[v] = (color[u] + 1) % 3
                        queue.append(v)

            output = [color[i] + 1 for i in range(n)]
            print(' '.join(map(str, output)))
        else:
            # Need 1 or 2 colors for bipartite graph
            if all(t[0] == t[i] for i in range(n)):
                # All same type
                print(1)
                print(' '.join(['1'] * n))
            else:
                # Output 2-coloring from BFS
                print(2)
                output = [color[i] + 1 for i in range(n)]
                print(' '.join(map(str, output)))

solve()
