for _ in range(t):
    n, m, k = map(int, input().split())
    cards_per_player = n // k

    # Case 1: One player takes all jokers
    if m <= cards_per_player and (k-1) * cards_per_player <= n - m:
        print(m - 0)

    # Case 2: Can't concentrate all jokers, distribute evenly
    else:
        # Winner gets ceil(m/k) jokers
        winner_jokers = (m + k - 1) // k
        # Other players get floor(m/k) jokers
        other_jokers = m // k

        # Check if the distribution is possible
        # Total jokers needed: winner_jokers + other_jokers * (k-1)
        if winner_jokers + other_jokers * (k-1) <= m:
            # Check if we can give winner_jokers jokers to one player
            if winner_jokers <= cards_per_player:
                # Check if we can give other_jokers jokers to others
                if other_jokers <= cards_per_player:
                    # Check if there are enough plain cards
                    if (cards_per_player - winner_jokers) + (cards_per_player - other_jokers) * (k-1) <= n - m:
                        print(winner_jokers - other_jokers)
                    else:
                        print(0)
                else:
                    print(0)
            else:
                print(0)
        else:
            print(0)
