def is_valid(grid, n, m, c_r, c_c):
    """Check if a 3x3 square centered at (c_r, c_c) is valid"""
    # Check bounds
    if c_r < 1 or c_r >= n-1 or c_c < 1 or c_c >= m-1:
        return False

    # Check each cell in the 3x3 square
    for i in range(c_r-1, c_r+2):
        for j in range(c_c-1, c_c+2):
            if i == c_r:
                # Middle row: center is empty
                if j == c_c:
                    if grid[i][j] != '.':
                        return False
                else:
                    if grid[i][j] != '#':
                        return False
            else:
                # Top and bottom rows: all filled
                if grid[i][j] != '#':
                    return False
    return True

n, m = map(int, input().split())
grid = [list(input().strip()) for _ in range(n)]

for i in range(n):
    for j in range(m):
        if grid[i][j] == '#':
            # Check if there's a valid 3x3 square that can fill this cell
            valid = False

            # Check if cell is in the middle row of some square
            if i >= 1 and i <= n-2:
                # Middle row: center at (i, j-1) or (i, j+1)
                if j >= 1 and is_valid(grid, n, m, i, j-1):
                    valid = True
                if j <= m-2 and is_valid(grid, n, m, i, j+1):
                    valid = True

            # Check if cell is in the top row of some square
            if i <= n-2 and (i == n-2 or i <= n-3):
                # Top row: center at (i+1, j-1), (i+1, j), (i+1, j+1)
                if j >= 1 and is_valid(grid, n, m, i+1, j-1):
                    valid = True
                if is_valid(grid, n, m, i+1, j):
                    valid = True
                if j <= m-2 and is_valid(grid, n, m, i+1, j+1):
                    valid = True

            # Check if cell is in the bottom row of some square
            if i >= 1 and (i >= 2 or i <= n-3):
                # Bottom row: center at (i-1, j-1), (i-1, j), (i-1, j+1)
                if j >= 1 and is_valid(grid, n, m, i-1, j-1):
