import sys

def range_max(query, l, r):
    """Find the maximum value in the range [l, r]"""
    if l == r:
        return query[l]
    mid = (l + r) // 2
    left_max = range_max(query, l, mid)
    right_max = range_max(query, mid + 1, r)
    return max(left_max, right_max)

n = int(sys.stdin.readline())
heights = list(map(int, sys.stdin.readline().split()))

# Build range maximum query structure
# For simplicity, I'll use a naive approach for now

# BFS to find shortest path
from collections import deque

# Distance array
dist = [float('inf')] * n
dist[0] = 0

# Queue for BFS
queue = deque([0])

while queue:
    i = queue.popleft()

    # Try jumping to i+1
    if i + 1 < n:
        if dist[i+1] == float('inf'):
            dist[i+1] = dist[i] + 1
            queue.append(i+1)

    # Try jumping to the farthest j where all values between i and j are < min(heights[i], heights[j])
    farthest = i + 1
    for j in range(i + 2, n):
        if range_max(heights, i + 1, j - 1) < min(heights[i], heights[j]):
            farthest = j
        else:
