def solve():
    n = int(input())
    targets = []
    for _ in range(n):
        x, y, t, p = input().split()
        targets.append((int(x), int(y), int(t), float(p)))

    # Sort by time
    targets.sort(key=lambda x: x[2])

    # dp[t] = maximum expected value we can get at time t
    # We'll use a dictionary to store positions and their max values
    dp = {}  # dp[time] = {(x, y): value}

    # At time 0, we start at (0, 0) with expected value 0
    dp[0] = {(0, 0): 0.0}

    for i, (x, y, t, p) in enumerate(targets):
        # If we haven't reached this time yet, just move forward
        if t not in dp:
            for time in range(min(t, 1000) + 1):  # Limit time to avoid infinite loops
                if time not in dp:
                    break

                # Move from all positions at time 'time' to all positions at time 't'
                for (ox, oy), val in dp[time].items():
                    # Move from (ox, oy) to (x, y) in time t - time
                    dist = abs(ox - x) + abs(oy - y)  # Manhattan distance
                    if dist <= t - time:
                        if t not in dp:
                            dp[t] = {}
                        dp[t][(x, y)] = max(dp[t].get((x, y), 0.0), val + p)
            continue

        # We've reached time t
        # First, propagate from all previous times to time t
        for prev_time in range(t):
            if prev_time not in dp:
                break

            for (ox, oy), val in dp[prev_time].items():
                # Move from (ox, oy) to (x, y) in time t - prev_time
                dist = abs(ox - x) + abs(oy - y)
                if dist <= t - prev_time:
                    if t not in dp:
                        dp[t] = {}
