    if i == first_a or i == first_b:
        continue
    # Ensure we don't have two same types in a row
    if types[i-1] == 0:
        # This is the first non-assigned chair
        # We can start with 1 or 2, but need to match the first assigned type
        if types[first_a] == 1:
            types[i] = 2
        else:
