def solve():
    n = int(sys.stdin.readline())
    pairs = []

    for i in range(n):
        a, b = map(int, sys.stdin.readline().split())
        pairs.append((a, b))

    # Try both alternating patterns
    def check_pattern(start_color):
        # start_color = 1 or 2
        color = {}
        for i in range(1, 2*n + 1):
            if i % 2 == 1:
                color[i] = start_color
            else:
                color[i] = 3 - start_color

        # Check if this pattern works
        valid = True
        for a, b in pairs:
            if color[a] == color[b]:
                valid = False
                break
        return valid

