import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Count items by weight
    count = [0] * 4  # count[1], count[2], count[3]

    for _ in range(n):
        w = int(next(it))
        c = int(next(it))
