n, m = map(int, input().split())
numbers = list(map(int, input().split()))

# Count remainders modulo m
remainder_count = {}
for num in numbers:
    rem = num % m
    remainder_count[rem] = remainder_count.get(rem, 0) + 1

# If any number is 0 modulo m, answer is YES
if 0 in remainder_count:
    print("YES")
    exit()

# If n >= m, there must be a solution by pigeonhole principle
if n >= m:
    print("YES")
    exit()

# Check if there are at least two numbers with the same remainder r such that 2*r % m == 0
found = False
for rem, count in remainder_count.items():
    if count >= 2 and (2 * rem) % m == 0:
        found = True
        break

# Check if there are remainders r1 and r2 such that r1 + r2 = m
if not found:
    for r1, count in remainder_count.items():
        r2 = m - r1
        if r2 in remainder_count:
            found = True
            break

print("YES" if found else "NO")
"}

