import sys

def min_segments(points):
    """Find minimum number of axis-aligned segments to connect three points."""
    if len(set(p[0] for p in points)) == 1:  # All same x (vertical line)
        return 1
    if len(set(p[1] for p in points)) == 1:  # All same y (horizontal line)
        return 1

    # Count how many points share same x or y
    same_x_count = len(set(p[0] for p in points))
    same_y_count = len(set(p[1] for p in points))

    # If two points share same x or y, we need 2 segments
    if same_x_count == 2 or same_y_count == 2:
        return 2

    # Otherwise, no two points share same line, need 3 segments
    return 3

def solve():
    points = []
    for _ in range(3):
        x, y = map(int, sys.stdin.readline().split())
        points.append((x, y))

    print(min_segments(points))

if __name__ == "__main__":
    solve()
"}

