n, x = map(int, input().split())
arr = list(map(int, input().split()))

# For each element, compute original and (value & x)
original_counts = {}
and_counts = {}

for val in arr:
    original_counts[val] = original_counts.get(val, 0) + 1
    and_val = val & x
    and_counts[and_val] = and_counts.get(and_val, 0) + 1

# Check if any value already has duplicate
for val in original_counts:
    if original_counts[val] >= 2:
        print(0)
        exit()

# Check if any value appears in both original and (value & x) forms
# across different elements
for val in original_counts:
    if val in and_counts:
        print(1)
        exit()

# If we get here, it's impossible
print(-1)
"}

