arr = list(map(int, input().split()))

# For each element, compute the set of values it can become
# and count how many elements can produce each value
value_counts = {}

for val in arr:
    v1 = val
    v2 = val & x

    # For each achievable value, count how many elements can produce it
    for v in [v1, v2]:
        value_counts[v] = value_counts.get(v, 0) + 1

# Check if any value can be produced by at least two different elements
# (this means we can apply operation to one element to make it match another)
for val in value_counts:
    if value_counts[val] >= 2:
        print(1)
        exit()

# Check if there's already a duplicate in original values (no operations needed)
for val in original_counts:
    if original_counts[val] >= 2:
        print(0)
        exit()

# If we get here, it's impossible
print(-1)
