    next_use[i] = []
    for b in range(1, n + 1):
        if b == a[i]:
            next_use[i].append(i)
        else:
            next_use[i].append(n + 1)

# Or simpler: compute next_use for each index and each book
# We'll compute it as a list of dictionaries
