    print(max_len, best_pos)

s = input().strip()
n = int(input())
boring = [input().strip() for _ in range(n)]

# Check if a substring contains any boring substring
contains_boring = False
for b in boring:
    if b in s:
        contains_boring = True
        break

if not contains_boring:
    # All characters are valid, return the whole string
    print(len(s), 0)
else:
    # Find the longest valid substring
    max_len = 0
    best_pos = 0

    # Try each starting position
    for start in range(len(s)):
        # Try extending from this position
        for end in range(start, len(s)):
            # Check if substring s[start:end+1] contains any boring substring
            valid = True
            for b in boring:
                if b in s[start:end+1]:
                    valid = False
                    break

            if valid:
                current_len = end - start + 1
                if current_len > max_len or (current_len == max_len and start < best_pos):
                    max_len = current_len
                    best_pos = start

    print(max_len, best_pos)
